      /* ★★ 217 轮：**"这是我们在滚"**的证据 —— `onListScroll` 靠它把"程序滚动"
         与"用户滚轮"分开。不写它的话，识别回填那一次补滚会被自己判成"用户滚了"，
         当场把记录区收掉（216 续那 120ms 复核要防的就是这件事）。
         ⚠️ 600ms 是"动画走完 ＋ 折行重排"的量级，与 `_touching` 同源。 */
      this._autoUntil = Date.now() + 600;
